# -*- coding: utf-8 -*-
"""
BÀI SÁP NHẬP V4.5.1 - CHUẨN HÓA GIAO DIỆN

- Bỏ nút SÁP NHẬP PHÁT SINH khỏi màn hình Sáp nhập trường bên ngoài.
- Chỉ giữ SÁP NHẬP PHÁT SINH trong Bảng điều khiển toàn tỉnh.
- Trong Sáp nhập phát sinh: chọn Xã/phường -> Cấp học -> Năm hiệu lực -> Nguồn/Đích.
- Danh sách Nguồn/Đích chỉ nạp các trường đang hoạt động đúng xã/phường + cấp học đã chọn.
- Không thực hiện sáp nhập; không chủ động ghi phocap.db.
"""
from __future__ import annotations
import base64, datetime as dt, hashlib, json, os, py_compile, shutil, sys, traceback
from pathlib import Path

TITLE = "BÀI SÁP NHẬP V4.5.1 - CHUẨN HÓA GIAO DIỆN"
EMBEDDED_FILES = {'app/templates/data_tools/school_merger.html': '', 'app/routers/school_merger_future.py': '', 'app/templates/data_tools/school_merger_future_v45.html': '', 'app/templates/data_tools/school_merger_future_preview_v45.html': ''}
EXPECTED_V45_HASHES = {'app/templates/data_tools/school_merger.html': '0b5d9d302987e3112db54e13bbb8c8955e329ec7506d5f1a26832676154397f3', 'app/routers/school_merger_future.py': 'a4457f453962f9377300a0ee55efd2661c93636b9f101607df3e7e1dcd417e18', 'app/templates/data_tools/school_merger_future_v45.html': '555110756c9cf3334f3b910df857719ebba70287d3bf6dbf8a0db9fdd0609843', 'app/templates/data_tools/school_merger_future_preview_v45.html': '3afe83aeea38876f426a20d588ec37bb523917a006fb39b6526d50371b77bcbb'}
FINAL_HASHES = {'app/templates/data_tools/school_merger.html': '8b8c5fbf899755056fcdfcfc91d1247049ca92163a2c1e5e8e1573cf5ebf833d', 'app/routers/school_merger_future.py': '4995f619f1b7424a16d440f0d8244430525182e3cc149d3909f56540d3e6f870', 'app/templates/data_tools/school_merger_future_v45.html': 'a37b7e2b3676ccec0ebfaa3deac3b07b7003d0412213528e99ce344f805e5bfa', 'app/templates/data_tools/school_merger_future_preview_v45.html': '194e13ff108865250862e43074b4109cb6b3ff12a0f6342068e9e460e05315d7'}

def sha256_file(p: Path) -> str:
    h=hashlib.sha256()
    with p.open('rb') as f:
        for chunk in iter(lambda:f.read(1024*1024), b''):
            h.update(chunk)
    return h.hexdigest()

def db_fingerprint(db: Path) -> str:
    h=hashlib.sha256()
    for p in [db, Path(str(db)+'-wal'), Path(str(db)+'-shm')]:
        h.update(str(p.name).encode('utf-8'))
        if p.exists():
            h.update(str(p.stat().st_size).encode('ascii'))
            h.update(sha256_file(p).encode('ascii'))
        else:
            h.update(b'MISSING')
    return h.hexdigest()

def fail(msg: str):
    raise RuntimeError(msg)

def main():
    cwd=Path.cwd().resolve()
    script_dir=Path(__file__).resolve().parent
    root=cwd if (cwd/'app').exists() else script_dir
    if not (root/'app').exists():
        fail('Không tìm thấy thư mục app. Hãy chép bộ cài vào C:\\PhoCap và chạy tại C:\\PhoCap.')
    db=root/'data'/'phocap.db'
    if not db.exists():
        fail(f'Không tìm thấy database: {db}')
    ts=dt.datetime.now().strftime('%Y%m%d_%H%M%S')
    backup_dir=root/'backups'/f'backup_truoc_bai_sap_nhap_v4_5_1_{ts}'
    export_dir=root/'exports'/'Bai_Sap_Nhap_V4_5_1_Chuan_Hoa_Giao_Dien'
    report_path=export_dir/f'bao_cao_v4_5_1_{ts}.json'
    db_before=db_fingerprint(db)
    touched=[]
    existed={}
    try:
        # Kiểm tra đúng nền V4.5 hoặc cho phép chạy lại V4.5.1.
        for rel in EMBEDDED_FILES:
            p=root/rel
            if not p.exists():
                fail(f'Thiếu tệp nền: {rel}')
            cur=sha256_file(p)
            allowed={EXPECTED_V45_HASHES[rel], FINAL_HASHES[rel]}
            if cur not in allowed:
                fail(f'Tệp {rel} không đúng nền V4.5/V4.5.1 đã khóa. SHA hiện tại={cur}')
        backup_dir.mkdir(parents=True, exist_ok=True)
        for rel in EMBEDDED_FILES:
            src=root/rel
            existed[rel]=src.exists()
            dst=backup_dir/rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src,dst)
        # Ghi toàn bộ tệp hoàn chỉnh.
        for rel,b64 in EMBEDDED_FILES.items():
            p=root/rel
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_bytes(base64.b64decode(b64))
            touched.append(rel)
        # Kiểm tra SHA và cú pháp Python.
        for rel,expected_hash in FINAL_HASHES.items():
            got=sha256_file(root/rel)
            if got!=expected_hash:
                fail(f'SHA sau cài không đúng: {rel}')
        py_compile.compile(str(root/'app/routers/school_merger_future.py'), doraise=True)
        # Kiểm tra cấu trúc giao diện bắt buộc.
        outer=(root/'app/templates/data_tools/school_merger.html').read_text(encoding='utf-8')
        future=(root/'app/templates/data_tools/school_merger_future_v45.html').read_text(encoding='utf-8')
        dashboard=(root/'app/templates/data_tools/school_merger_dashboard_v45.html').read_text(encoding='utf-8')
        router=(root/'app/routers/school_merger_future.py').read_text(encoding='utf-8')
        if 'href="/cong-cu-du-lieu/sap-nhap-truong/phat-sinh">SÁP NHẬP PHÁT SINH</a>' in outer:
            fail('Nút SÁP NHẬP PHÁT SINH vẫn còn ở màn hình ngoài.')
        if '/cong-cu-du-lieu/sap-nhap-truong/phat-sinh' not in dashboard:
            fail('Bảng điều khiển không còn nút SÁP NHẬP PHÁT SINH.')
        for needle in ['BƯỚC 1','Xã/phường','BƯỚC 2','Cấp học','TRƯỜNG NGUỒN','TRƯỜNG ĐÍCH']:
            if needle not in future:
                fail(f'Thiếu thành phần giao diện: {needle}')
        if 'commune_id: str | None = Query(default=None)' not in router or 'commune_id=commune_id_int' not in router:
            fail('Router chưa lọc trường theo xã/phường.')
        db_after=db_fingerprint(db)
        if db_after!=db_before:
            fail('Database/WAL đã thay đổi trong bộ cài. Đã dừng an toàn.')
        export_dir.mkdir(parents=True, exist_ok=True)
        report={
            'installed_at':dt.datetime.now().isoformat(timespec='seconds'),
            'title':TITLE,
            'database_unchanged':True,
            'backup_dir':str(backup_dir),
            'changes':[
                'Bỏ SÁP NHẬP PHÁT SINH khỏi màn hình Sáp nhập trường bên ngoài.',
                'Chỉ giữ SÁP NHẬP PHÁT SINH trong Bảng điều khiển toàn tỉnh.',
                'Luồng phát sinh: Xã/phường -> Cấp học -> Năm hiệu lực -> Nguồn/Đích.',
                'Nguồn/Đích lọc theo đúng xã/phường + cấp học đang chọn.',
            ],
            'files':{rel:{'sha256':FINAL_HASHES[rel]} for rel in EMBEDDED_FILES},
        }
        report_path.write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
        print()
        print('='*104)
        print('BÀI SÁP NHẬP V4.5.1 - CÀI ĐẶT THÀNH CÔNG')
        print('Database: KHÔNG THAY ĐỔI')
        print('Đã bỏ SÁP NHẬP PHÁT SINH khỏi màn hình ngoài; chỉ giữ trong Bảng điều khiển toàn tỉnh.')
        print('Luồng phát sinh: Xã/phường -> Cấp học -> Năm hiệu lực -> Nguồn -> Đích.')
        print(f'Backup mã nguồn trước V4.5.1: {backup_dir}')
        print(f'Báo cáo: {report_path}')
        print('='*104)
    except Exception as e:
        try:
            for rel in touched:
                bp=backup_dir/rel
                if bp.exists():
                    p=root/rel
                    p.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(bp,p)
        except Exception:
            pass
        print()
        print('='*104)
        print('DỪNG AN TOÀN - BÀI SÁP NHẬP V4.5.1')
        print('Mã nguồn đã được khôi phục nếu đã chạm file.')
        print(f'Lỗi: {e}')
        print('Bộ cài KHÔNG thực hiện sáp nhập và KHÔNG chủ động ghi phocap.db.')
        print('='*104)
        if os.environ.get('PHOCAP_INSTALLER_DEBUG')=='1': traceback.print_exc()
        raise SystemExit(1)

if __name__=='__main__':
    main()
